const outputText = $input.first().json.stdout || '';
const lines = outputText.split('\n').filter(l => l.trim().length > 0);
const results = [];

const SQLI_REGEX = /(?:union(?:\s+all)?\s+select|'\s+or\s+'1'='1|information_schema)/i;
const XSS_REGEX = /<script.*?>|javascript:|onerror\s*=/i;
const TRAVERSAL_REGEX = /\.\.\/\.\.\//i;

for (const line of lines) {
  let matched = false;
  let component = 'frontend';
  let is_security = false;
  let severity = 'P2';
  let source = 'nextjs';

  if (SQLI_REGEX.test(line)) {
    matched = true;
    component = 'auth';
    is_security = true;
    severity = 'P1';
    source = 'security-scanner';
  } else if (XSS_REGEX.test(line) || TRAVERSAL_REGEX.test(line)) {
    matched = true;
    component = 'frontend';
    is_security = true;
    severity = 'P1';
    source = 'security-scanner';
  } else if (line.includes('MongoNetworkError') || line.includes('ECONNREFUSED') || line.includes('serverSelectionTimeoutMS')) {
    matched = true;
    component = 'database';
    is_security = false;
    severity = 'P1';
    source = 'mongodb';
  } else if (line.includes('OOM') || line.includes('out of memory') || line.includes('stress-ng')) {
    matched = true;
    component = 'frontend';
    is_security = false;
    severity = 'P1';
    source = 'nextjs';
  }

  if (matched) {
    results.push({
      json: {
        incident_id: require('crypto').randomUUID(),
        source: source,
        timestamp: new Date().toISOString(),
        component: component,
        raw_log: line.trim(),
        is_security_event: is_security,
        severity_hint: severity
      }
    });
  }
}

return results;
